-- MVP Phase 1-4 conceptual MySQL schema.
-- Canonical application schema: src/db/schema.ts
CREATE TABLE organizations (id BIGINT AUTO_INCREMENT PRIMARY KEY,parent_id BIGINT NULL,organization_type VARCHAR(50) NOT NULL,code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE study_programs (id BIGINT AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT NOT NULL,code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,level VARCHAR(50),status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE roles (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL);
CREATE TABLE permissions (id BIGINT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(150) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL);
CREATE TABLE role_permissions (role_id BIGINT NOT NULL,permission_id BIGINT NOT NULL,PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_roles (user_id BIGINT NOT NULL,role_id BIGINT NOT NULL,organization_id BIGINT NOT NULL,study_program_id BIGINT NULL,PRIMARY KEY(user_id,role_id,organization_id));
CREATE TABLE strategic_plans (id BIGINT AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT NOT NULL,title VARCHAR(500) NOT NULL,period_start INT NOT NULL,period_end INT NOT NULL,version_number INT NOT NULL DEFAULT 1,lifecycle_status VARCHAR(30) NOT NULL DEFAULT 'DRAFT',effective_from DATE NULL,effective_to DATE NULL);
CREATE TABLE strategic_statements (id BIGINT AUTO_INCREMENT PRIMARY KEY,organization_id BIGINT NOT NULL,plan_id BIGINT NULL,statement_type VARCHAR(30) NOT NULL,code VARCHAR(50),sequence INT NOT NULL DEFAULT 1,statement TEXT NOT NULL,version_number INT NOT NULL DEFAULT 1,lifecycle_status VARCHAR(30) NOT NULL DEFAULT 'DRAFT',effective_from DATE NULL,effective_to DATE NULL);
CREATE TABLE strategic_goals (id BIGINT AUTO_INCREMENT PRIMARY KEY,plan_id BIGINT NOT NULL,organization_id BIGINT NOT NULL,code VARCHAR(50),title VARCHAR(500) NOT NULL,description TEXT,lifecycle_status VARCHAR(30) NOT NULL DEFAULT 'DRAFT');
CREATE TABLE kpis (id BIGINT AUTO_INCREMENT PRIMARY KEY,strategic_goal_id BIGINT NOT NULL,owner_organization_id BIGINT NOT NULL,code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(500) NOT NULL,definition TEXT,formula TEXT,unit VARCHAR(50),direction VARCHAR(30) NOT NULL DEFAULT 'HIGHER_IS_BETTER',lifecycle_status VARCHAR(30) NOT NULL DEFAULT 'DRAFT');
CREATE TABLE kpi_targets (id BIGINT AUTO_INCREMENT PRIMARY KEY,kpi_id BIGINT NOT NULL,period VARCHAR(30) NOT NULL,target_value DECIMAL(18,4) NOT NULL,UNIQUE(kpi_id,period));
CREATE TABLE kpi_measurements (id BIGINT AUTO_INCREMENT PRIMARY KEY,kpi_id BIGINT NOT NULL,period VARCHAR(30) NOT NULL,actual_value DECIMAL(18,4) NOT NULL,achievement_percent DECIMAL(10,4),status VARCHAR(30),workflow_status VARCHAR(30) NOT NULL DEFAULT 'DRAFT',measured_by BIGINT NOT NULL,measured_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(kpi_id,period));
CREATE TABLE evidences (id BIGINT AUTO_INCREMENT PRIMARY KEY,subject_type VARCHAR(100) NOT NULL,subject_id BIGINT NOT NULL,title VARCHAR(500) NOT NULL,storage_key VARCHAR(1000) NOT NULL,mime_type VARCHAR(150),checksum VARCHAR(128),visibility VARCHAR(20) NOT NULL DEFAULT 'INTERNAL',uploaded_by BIGINT NOT NULL,uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE evaluations (id BIGINT AUTO_INCREMENT PRIMARY KEY,subject_type VARCHAR(100) NOT NULL,subject_id BIGINT NOT NULL,period VARCHAR(30),standard_reference TEXT,standard_value VARCHAR(255),actual_value VARCHAR(255),gap_value VARCHAR(255),analysis TEXT,root_cause TEXT,public_summary TEXT,evaluator_id BIGINT NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'DRAFT',evaluated_at TIMESTAMP NULL);
CREATE TABLE findings (id BIGINT AUTO_INCREMENT PRIMARY KEY,evaluation_id BIGINT NOT NULL,severity VARCHAR(30),category VARCHAR(100),description TEXT NOT NULL,is_public_candidate BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE recommendations (id BIGINT AUTO_INCREMENT PRIMARY KEY,evaluation_id BIGINT NOT NULL,priority VARCHAR(30),recommendation_text TEXT NOT NULL,owner_organization_id BIGINT NULL,target_completion DATE NULL,status VARCHAR(30) NOT NULL DEFAULT 'OPEN');
CREATE TABLE followups (id BIGINT AUTO_INCREMENT PRIMARY KEY,recommendation_id BIGINT NOT NULL,action_plan TEXT NOT NULL,pic_user_id BIGINT NULL,start_date DATE NULL,due_date DATE NULL,progress_percent DECIMAL(5,2) NOT NULL DEFAULT 0,status VARCHAR(30) NOT NULL DEFAULT 'OPEN');
CREATE TABLE followup_verifications (id BIGINT AUTO_INCREMENT PRIMARY KEY,followup_id BIGINT NOT NULL,verifier_id BIGINT NOT NULL,effective BOOLEAN NULL,verification_note TEXT,verified_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE approvals (id BIGINT AUTO_INCREMENT PRIMARY KEY,subject_type VARCHAR(100) NOT NULL,subject_id BIGINT NOT NULL,approval_level VARCHAR(100) NOT NULL,decision VARCHAR(30) NOT NULL,approver_id BIGINT NOT NULL,note TEXT,decided_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE publication_policies (id BIGINT AUTO_INCREMENT PRIMARY KEY,subject_type VARCHAR(100) NOT NULL,policy_version INT NOT NULL DEFAULT 1,allowed_fields JSON NOT NULL,required_lifecycle_status VARCHAR(30),requires_approval BOOLEAN NOT NULL DEFAULT TRUE,status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE publications (id BIGINT AUTO_INCREMENT PRIMARY KEY,subject_type VARCHAR(100) NOT NULL,subject_id BIGINT NOT NULL,policy_id BIGINT NULL,visibility VARCHAR(20) NOT NULL DEFAULT 'INTERNAL',public_title VARCHAR(500),public_summary TEXT,field_policy_snapshot JSON,publication_start TIMESTAMP NULL,publication_end TIMESTAMP NULL,approved_by BIGINT NULL,published_by BIGINT NULL,published_at TIMESTAMP NULL,status VARCHAR(30) NOT NULL DEFAULT 'DRAFT');
CREATE TABLE object_versions (id BIGINT AUTO_INCREMENT PRIMARY KEY,subject_type VARCHAR(100) NOT NULL,subject_id BIGINT NOT NULL,version_number INT NOT NULL,snapshot JSON NOT NULL,changed_by BIGINT NOT NULL,reason TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT NULL,action VARCHAR(100) NOT NULL,subject_type VARCHAR(100) NOT NULL,subject_id BIGINT NULL,before_json JSON NULL,after_json JSON NULL,reason TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
